-- ImprintSites AI — initial schema
-- All IDs are opaque random strings generated by the application.
-- Money is stored as integer minor units (cents) with an explicit currency.

PRAGMA foreign_keys = ON;

-- ───────────────────────── Identity ─────────────────────────
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name TEXT NOT NULL DEFAULT '',
  password_hash TEXT,                    -- null for Google-only accounts
  google_sub TEXT UNIQUE,
  email_verified INTEGER NOT NULL DEFAULT 0,
  role TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer','admin')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')),
  avatar_url TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,                   -- sha256(token) hex; raw token only in cookie
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  ip_hash TEXT,
  user_agent TEXT
);
CREATE INDEX idx_sessions_user ON sessions(user_id);

CREATE TABLE password_resets (
  id TEXT PRIMARY KEY,                   -- sha256(token)
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  used_at INTEGER,
  created_by TEXT                        -- 'self' or admin user id
);

CREATE TABLE teams (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  owner_id TEXT NOT NULL REFERENCES users(id),
  created_at INTEGER NOT NULL
);

-- ───────────────────────── Catalog of site types & templates ─────────────────────────
CREATE TABLE site_types (
  id TEXT PRIMARY KEY CHECK (id IN ('personal','business','ecommerce')),
  name TEXT NOT NULL,
  price_cents INTEGER NOT NULL,
  currency TEXT NOT NULL DEFAULT 'USD'
);
INSERT INTO site_types (id, name, price_cents, currency) VALUES
  ('personal', 'Personal / Portfolio', 2000, 'USD'),
  ('business', 'Business', 3000, 'USD'),
  ('ecommerce', 'E-commerce', 10000, 'USD');

CREATE TABLE templates (
  id TEXT PRIMARY KEY,
  site_type TEXT NOT NULL REFERENCES site_types(id),
  name TEXT NOT NULL,
  tier TEXT NOT NULL DEFAULT 'public' CHECK (tier IN ('public','member')),
  active INTEGER NOT NULL DEFAULT 1
);

-- ───────────────────────── Projects & site content ─────────────────────────
CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL REFERENCES users(id),
  team_id TEXT REFERENCES teams(id),
  site_type TEXT NOT NULL REFERENCES site_types(id),
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  template_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft','generating','preview_ready','payment_pending','published','suspended','deleted')),
  draft_json TEXT,                       -- current editable SiteDoc
  draft_revision INTEGER NOT NULL DEFAULT 0,
  is_demo INTEGER NOT NULL DEFAULT 0,
  content_rights_ack_at INTEGER,         -- user asserted rights to uploaded content
  ai_review_ack_at INTEGER,              -- user reviewed AI-suggested text
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  deleted_at INTEGER
);
CREATE INDEX idx_projects_owner ON projects(owner_id, updated_at DESC);

CREATE TABLE project_members (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('owner','editor','staff')),
  created_at INTEGER NOT NULL,
  PRIMARY KEY (project_id, user_id)
);

CREATE TABLE project_intake (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  step INTEGER NOT NULL DEFAULT 0,
  data_json TEXT NOT NULL DEFAULT '{}',
  completed_at INTEGER,
  updated_at INTEGER NOT NULL
);

-- Pages and blocks are denormalised snapshots of the SiteDoc for querying/reporting;
-- the SiteDoc JSON (draft_json / site_versions.doc_json) is the source of truth for rendering.
CREATE TABLE site_pages (
  id TEXT NOT NULL,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  position INTEGER NOT NULL,
  PRIMARY KEY (project_id, id)
);
CREATE TABLE site_blocks (
  id TEXT NOT NULL,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  page_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  position INTEGER NOT NULL,
  PRIMARY KEY (project_id, id)
);

CREATE TABLE draft_history (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL,
  doc_json TEXT NOT NULL,
  note TEXT,
  created_by TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_draft_history ON draft_history(project_id, revision DESC);

CREATE TABLE site_versions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  version INTEGER NOT NULL,
  doc_json TEXT NOT NULL,
  created_by TEXT,
  created_at INTEGER NOT NULL,
  note TEXT,
  UNIQUE (project_id, version)
);

CREATE TABLE site_assets (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,
  owner_id TEXT NOT NULL REFERENCES users(id),
  kind TEXT NOT NULL CHECK (kind IN ('image','document','screenshot')),
  mime TEXT NOT NULL,
  bytes INTEGER NOT NULL,
  width INTEGER,
  height INTEGER,
  original_name TEXT,
  storage TEXT NOT NULL CHECK (storage IN ('r2','d1')),
  storage_key TEXT NOT NULL,
  alt TEXT NOT NULL DEFAULT '',
  source TEXT NOT NULL DEFAULT 'upload',  -- upload | openverse | browser_capture
  license TEXT,
  attribution TEXT,
  source_url TEXT,
  visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public','private')),
  sha256 TEXT,
  created_at INTEGER NOT NULL,
  deleted_at INTEGER
);
CREATE INDEX idx_assets_project ON site_assets(project_id, created_at DESC);
CREATE INDEX idx_assets_owner ON site_assets(owner_id);

-- Fallback blob storage while R2 is not enabled. Chunks of up to ~1.5 MB.
CREATE TABLE asset_blobs (
  asset_id TEXT NOT NULL,
  chunk INTEGER NOT NULL,
  data BLOB NOT NULL,
  PRIMARY KEY (asset_id, chunk)
);

-- ───────────────────────── Generation / inspiration / publishing ─────────────────────────
CREATE TABLE generation_jobs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('deterministic','ai_copy','ai_refine','rule_refine')),
  status TEXT NOT NULL CHECK (status IN ('running','succeeded','failed')),
  provider TEXT,
  model TEXT,
  input_tokens INTEGER,
  output_tokens INTEGER,
  error TEXT,
  created_at INTEGER NOT NULL,
  finished_at INTEGER
);
CREATE INDEX idx_genjobs_project ON generation_jobs(project_id, created_at DESC);

CREATE TABLE inspiration_references (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL,
  url TEXT,
  method TEXT NOT NULL CHECK (method IN ('browser','html','screenshot','manual')),
  status TEXT NOT NULL CHECK (status IN ('ok','failed')),
  brief_json TEXT,
  screenshot_asset_id TEXT,
  error TEXT,
  created_at INTEGER NOT NULL
);

CREATE TABLE publication_jobs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('publish','unpublish','rollback','suspend')),
  version INTEGER,
  status TEXT NOT NULL CHECK (status IN ('succeeded','failed')),
  error TEXT,
  created_at INTEGER NOT NULL
);

CREATE TABLE published_sites (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  slug TEXT NOT NULL UNIQUE,
  current_version_id TEXT REFERENCES site_versions(id),
  status TEXT NOT NULL CHECK (status IN ('live','unpublished','suspended')),
  first_published_at INTEGER NOT NULL,
  last_published_at INTEGER NOT NULL
);

CREATE TABLE domains (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  hostname TEXT NOT NULL UNIQUE COLLATE NOCASE,
  kind TEXT NOT NULL CHECK (kind IN ('platform_subdomain','custom')),
  status TEXT NOT NULL DEFAULT 'requested'
    CHECK (status IN ('requested','pending_dns','pending_tls','active','failed','not_available')),
  verification_json TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

-- ───────────────────────── Commerce (customer storefronts) ─────────────────────────
CREATE TABLE collections (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  handle TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  position INTEGER NOT NULL DEFAULT 0,
  UNIQUE (project_id, handle)
);

CREATE TABLE products (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  handle TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  product_type TEXT NOT NULL DEFAULT 'physical' CHECK (product_type IN ('physical','digital')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','draft','archived')),
  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),
  compare_at_cents INTEGER CHECK (compare_at_cents IS NULL OR compare_at_cents >= 0),
  cost_cents INTEGER,
  currency TEXT NOT NULL,
  sku TEXT,
  weight_grams INTEGER,
  dimensions TEXT,
  tags TEXT NOT NULL DEFAULT '',
  images_json TEXT NOT NULL DEFAULT '[]',   -- [{assetId, alt}]
  option1_name TEXT,
  option2_name TEXT,
  max_per_order INTEGER NOT NULL DEFAULT 10,
  featured INTEGER NOT NULL DEFAULT 0,
  position INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (project_id, handle)
);
CREATE INDEX idx_products_project ON products(project_id, status, position);
CREATE UNIQUE INDEX idx_products_sku ON products(project_id, sku) WHERE sku IS NOT NULL AND sku <> '';

CREATE TABLE product_collections (
  product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  collection_id TEXT NOT NULL REFERENCES collections(id) ON DELETE CASCADE,
  PRIMARY KEY (product_id, collection_id)
);

CREATE TABLE product_variants (
  id TEXT PRIMARY KEY,
  product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL DEFAULT 'Default',
  option1 TEXT,
  option2 TEXT,
  sku TEXT,
  price_cents INTEGER CHECK (price_cents IS NULL OR price_cents >= 0),
  stock INTEGER NOT NULL DEFAULT 0,
  track_inventory INTEGER NOT NULL DEFAULT 1,
  allow_backorder INTEGER NOT NULL DEFAULT 0,
  position INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_variants_product ON product_variants(product_id, position);

-- Prevent overselling atomically: any batch that would push tracked stock below zero aborts.
CREATE TRIGGER trg_variant_no_oversell
BEFORE UPDATE OF stock ON product_variants
WHEN NEW.stock < 0 AND NEW.track_inventory = 1 AND NEW.allow_backorder = 0
BEGIN
  SELECT RAISE(ABORT, 'OUT_OF_STOCK');
END;

CREATE TABLE inventory_movements (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  variant_id TEXT NOT NULL,
  delta INTEGER NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('initial','manual_adjust','order','order_cancel','import')),
  order_id TEXT,
  actor TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_invmov_variant ON inventory_movements(variant_id, created_at DESC);

CREATE TABLE product_imports (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL,
  rows_total INTEGER NOT NULL,
  rows_created INTEGER NOT NULL,
  rows_updated INTEGER NOT NULL,
  rows_failed INTEGER NOT NULL,
  errors_json TEXT NOT NULL DEFAULT '[]',
  created_at INTEGER NOT NULL
);

CREATE TABLE carts (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE cart_items (
  cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,
  variant_id TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  PRIMARY KEY (cart_id, variant_id)
);

CREATE TABLE customer_contacts (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  marketing_consent INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
);

CREATE TABLE orders (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  number INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','confirmed','processing','ready_for_pickup','shipped','delivered','cancelled','refunded')),
  payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','paid','refunded')),
  payment_method TEXT NOT NULL,
  fulfillment_method TEXT NOT NULL,
  fulfillment_label TEXT NOT NULL,
  customer_contact_id TEXT,
  customer_name TEXT NOT NULL,
  customer_email TEXT,
  customer_phone TEXT,
  address_json TEXT,
  notes TEXT,
  currency TEXT NOT NULL,
  subtotal_cents INTEGER NOT NULL,
  shipping_cents INTEGER NOT NULL,
  total_cents INTEGER NOT NULL,
  access_token_hash TEXT NOT NULL,
  is_demo INTEGER NOT NULL DEFAULT 0,
  idempotency_key TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (project_id, number),
  UNIQUE (project_id, idempotency_key)
);
CREATE INDEX idx_orders_project ON orders(project_id, created_at DESC);

CREATE TABLE order_items (
  id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL,
  variant_id TEXT NOT NULL,
  title TEXT NOT NULL,
  variant_title TEXT,
  sku TEXT,
  unit_price_cents INTEGER NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  line_total_cents INTEGER NOT NULL
);

CREATE TABLE order_status_history (
  id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  from_status TEXT,
  to_status TEXT NOT NULL,
  payment_status TEXT,
  note TEXT,
  actor TEXT,
  created_at INTEGER NOT NULL
);

CREATE TABLE merchant_payment_connections (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  provider TEXT NOT NULL,                 -- manual | flutterwave | pesapal | paystack
  status TEXT NOT NULL CHECK (status IN ('manual','not_connected','pending_verification','connected','disabled')),
  public_config_json TEXT NOT NULL DEFAULT '{}', -- never secrets
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (project_id, provider)
);

-- ───────────────────────── Builder billing (the platform's own service) ─────────────────────────
CREATE TABLE builder_checkout_sessions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  site_type TEXT NOT NULL,
  amount_cents INTEGER NOT NULL,
  currency TEXT NOT NULL,
  provider TEXT NOT NULL,
  mode TEXT NOT NULL CHECK (mode IN ('test','live')),
  provider_session_id TEXT,
  status TEXT NOT NULL CHECK (status IN ('created','redirected','completed','failed','expired')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE payments (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  provider_payment_id TEXT NOT NULL,
  mode TEXT NOT NULL CHECK (mode IN ('test','live')),
  checkout_session_id TEXT,
  project_id TEXT,
  user_id TEXT,
  amount_cents INTEGER NOT NULL,
  currency TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('succeeded','failed','processing','cancelled','refunded','partially_refunded')),
  raw_status TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (provider, provider_payment_id)
);

CREATE TABLE webhook_events (
  id TEXT PRIMARY KEY,                    -- provider webhook-id (idempotency key)
  provider TEXT NOT NULL,
  event_type TEXT NOT NULL,
  received_at INTEGER NOT NULL,
  processed_at INTEGER,
  status TEXT NOT NULL CHECK (status IN ('received','processed','ignored','failed')),
  error TEXT,
  payload_digest TEXT
);

CREATE TABLE entitlements (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  site_type TEXT NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('payment_live','payment_test','admin_demo')),
  payment_id TEXT,
  granted_by TEXT,
  reason TEXT,
  status TEXT NOT NULL CHECK (status IN ('active','revoked')),
  created_at INTEGER NOT NULL,
  revoked_at INTEGER
);
CREATE INDEX idx_entitlements_project ON entitlements(project_id, status);

CREATE TABLE invoices (
  id TEXT PRIMARY KEY,
  payment_id TEXT NOT NULL REFERENCES payments(id),
  provider_invoice_url TEXT,
  created_at INTEGER NOT NULL
);

-- ───────────────────────── Leads, support, compliance ─────────────────────────
CREATE TABLE contact_leads (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  message TEXT NOT NULL,
  page TEXT,
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','read','archived')),
  ip_hash TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_leads_project ON contact_leads(project_id, created_at DESC);

CREATE TABLE quote_requests (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  service TEXT,
  budget TEXT,
  timeline TEXT,
  details TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','read','archived')),
  ip_hash TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_quotes_project ON quote_requests(project_id, created_at DESC);

CREATE TABLE support_tickets (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  category TEXT NOT NULL CHECK (category IN ('general','sales','billing','technical','ip_report','abuse_report','privacy')),
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  subject TEXT NOT NULL,
  message TEXT NOT NULL,
  reference_url TEXT,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','resolved','closed')),
  admin_note TEXT,
  ip_hash TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE consents (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  project_id TEXT,
  kind TEXT NOT NULL,                     -- terms | privacy | content_rights | ai_review | checkout_data
  version TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  actor_id TEXT,
  action TEXT NOT NULL,
  target_type TEXT,
  target_id TEXT,
  detail_json TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_audit_created ON audit_logs(created_at DESC);

CREATE TABLE system_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_by TEXT,
  updated_at INTEGER NOT NULL
);
