  ('support_email', '', 0);

CREATE TABLE rate_limits (
  key TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  count INTEGER NOT NULL,
  PRIMARY KEY (key, window_start)
);

CREATE TABLE error_events (
  id TEXT PRIMARY KEY,
  route TEXT,
  message TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
